import{_ as t,o as s,c as a,a2 as i}from"./chunks/framework.CHeM0PsO.js";const k=JSON.parse('{"title":"Sovereign — Development Workflow","description":"","frontmatter":{"docSection":"contributors","docType":"guide","audiences":["contributor"],"sourceUrl":"https://github.com/sovereignfs/sovereign/blob/main/docs/development-workflow.md"},"headers":[],"relativePath":"development-workflow.md","filePath":"development-workflow.md"}'),o={name:"development-workflow.md"};function n(d,e,r,l,c,h){return s(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="sovereign-—-development-workflow" tabindex="-1">Sovereign — Development Workflow <a class="header-anchor" href="#sovereign-—-development-workflow" aria-label="Permalink to &quot;Sovereign — Development Workflow&quot;">​</a></h1><p>How tasks are planned, started, implemented, and closed out. Designed for agentic execution with human oversight.</p><hr><h2 id="three-layer-information-architecture" tabindex="-1">Three-layer information architecture <a class="header-anchor" href="#three-layer-information-architecture" aria-label="Permalink to &quot;Three-layer information architecture&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CLAUDE.md / AGENTS.md      ← agent-specific adapter; conventions only (no task pointer)</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    └─▶ ROADMAP.md    ← chronological index; one row per PR; canonical status</span></span>
<span class="line"><span>            │</span></span>
<span class="line"><span>            └─▶ docs/epics/&lt;epic&gt;.md   ← full task detail: Goal, Deliverables,</span></span>
<span class="line"><span>                                           SRS reference, Review checklist</span></span></code></pre></div><p>Each layer has a single job:</p><table tabindex="0"><thead><tr><th>File</th><th>Job</th><th>What agents read it for</th></tr></thead><tbody><tr><td><code>CLAUDE.md</code> / <code>AGENTS.md</code></td><td>Agent-specific conventions</td><td>How to work; architectural rules; commit/PR conventions</td></tr><tr><td><code>ROADMAP.md</code></td><td>Version-ordered task index</td><td>Which tasks exist, their status, which epic file has the detail</td></tr><tr><td><code>docs/epics/&lt;file&gt;.md</code></td><td>Full task spec</td><td>Goal, deliverables, checklist for the active task</td></tr><tr><td><code>CURRENT_TASK.md</code></td><td>Active task scratch (transient)</td><td>Everything needed mid-task without re-navigating</td></tr><tr><td><code>docs/workstreams/&lt;file&gt;.md</code></td><td>Goal-ordered task sequence</td><td>Dependency order across epics, decisions already locked, gates</td></tr></tbody></table><blockquote><p><strong>Multi-agent note:</strong> The <code>⏳ Next</code> pointer previously in <code>CLAUDE.md</code> has been removed. The developer assigns the next task explicitly at session start. See <code>docs/multi-agent.md</code> for the full model.</p></blockquote><hr><h2 id="epic-structure" tabindex="-1">Epic structure <a class="header-anchor" href="#epic-structure" aria-label="Permalink to &quot;Epic structure&quot;">​</a></h2><p>Work is organized into domain epics. Each task has a <strong>stable epic task ID</strong> (<code>&lt;epic&gt;.&lt;seq&gt;</code>) that can be cited in PRs, RFCs, and commits independently of roadmap version numbers.</p><p>The epic index — every epic&#39;s ID, file, status, and summary — is <a href="./epics/README.html"><code>docs/epics/README.md</code></a>. It is the only copy; look IDs up there rather than in a table here that would drift.</p><h3 id="stable-ids-vs-volatile-slots" tabindex="-1">Stable IDs vs volatile slots <a class="header-anchor" href="#stable-ids-vs-volatile-slots" aria-label="Permalink to &quot;Stable IDs vs volatile slots&quot;">​</a></h3><p><strong>Epic task IDs are permanent.</strong> Once an ID like <code>9.9</code> is assigned it never changes — it is the stable identifier for that unit of work. Use epic task IDs in doc cross-references, RFC <code>incorporated_into_plan</code> fields, and task dependency lists.</p><p><strong>Roadmap slot versions are volatile.</strong> A slot like <code>0.9.2</code> reflects current priority ordering and may shift when tasks are reprioritized (e.g. <code>0.9.5 → 0.9.1</code>). Always look up the live slot from <code>ROADMAP.md</code> rather than copying it from another doc; include roadmap slots only where the shipping order matters (upgrade notes, version maps).</p><hr><h2 id="workstreams-and-the-leg-contract" tabindex="-1">Workstreams and the leg contract <a class="header-anchor" href="#workstreams-and-the-leg-contract" aria-label="Permalink to &quot;Workstreams and the leg contract&quot;">​</a></h2><p>Epics group tasks by <strong>domain</strong>; a <strong>workstream</strong> (<code>docs/workstreams/</code>) groups them by <strong>goal</strong> and orders them across epics. A workstream exists so the developer can point at a feature and have it executed end to end without re-briefing at every step.</p><p>A workstream is divided into <strong>legs</strong>, and the leg is what makes that compatible with one-task-at-a-time review:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>leg = one branch = one PR = one review gate</span></span></code></pre></div><ul><li><strong>Within a leg</strong>, the agent implements every task in order, committing per task, without stopping for review between them.</li><li><strong>At the end of a leg</strong>, it verifies, opens a <strong>draft</strong> PR, and stops. It does not merge and does not start the next leg.</li><li><strong>Across legs</strong>, the existing rule is unchanged: the previous leg&#39;s PR must be merged before the next leg&#39;s branch is cut.</li></ul><p>So &quot;do not start a task on an unmerged PR&quot; is scoped to <strong>leg</strong> boundaries rather than task boundaries. That is the only workflow rule a workstream changes. <strong>Never merge a PR automatically</strong> is unaffected and not negotiable by a workstream.</p><p>Consequences:</p><ul><li><strong>One version bump per leg</strong>, not per task, since a leg is one PR. Semver follows the largest change in the leg.</li><li><strong>Branch name follows the leg</strong>, e.g. <code>feat/&lt;workstream-slug&gt;-leg-&lt;n&gt;</code>.</li><li><strong>A leg must be independently reviewable.</strong> If its PR is too large to review honestly, the leg was drawn too wide — split it. Legs are a reviewability unit first and an autonomy unit second.</li><li>A leg marked a <strong>gate</strong> determines whether later legs proceed at all; a negative result stops the workstream rather than being worked around.</li></ul><blockquote><p><strong>Wired into the skills.</strong> <code>/sv-task-start</code> accepts a leg assignment (&quot;workstream 0023 leg 5&quot;) and writes <code>CURRENT_TASK.md</code> in <strong>leg mode</strong> — the leg&#39;s detail block plus every task block in it. <code>/sv-task-complete</code> and <code>/sv-update-task-docs</code> read that mode: one verification pass, one version bump, every task&#39;s roadmap row and epic heading marked ✅, the workstream doc&#39;s changelog updated, and a stop at the draft PR.</p></blockquote><p>Full definition, required sections, and the authoring template: <a href="./workstreams/README.html"><code>docs/workstreams/README.md</code></a>.</p><hr><h2 id="task-lifecycle" tabindex="-1">Task lifecycle <a class="header-anchor" href="#task-lifecycle" aria-label="Permalink to &quot;Task lifecycle&quot;">​</a></h2><h3 id="starting-a-task" tabindex="-1">Starting a task <a class="header-anchor" href="#starting-a-task" aria-label="Permalink to &quot;Starting a task&quot;">​</a></h3><p>Run <code>/sv-task-start</code>. The skill:</p><ol><li>The developer specifies the task (epic task ID or description) or the workstream leg (&quot;workstream 0023 leg 5&quot;) — there is no <code>⏳ Next</code> pointer. See <code>docs/multi-agent.md</code>.</li><li>Confirms <code>main</code> is clean and pulls latest; for a leg, confirms the previous leg&#39;s PR is merged and the leg&#39;s &quot;Do not proceed if&quot; clause doesn&#39;t hold.</li><li>Looks up the epic file via <code>docs/epics/README.md</code>, then greps for the task heading to extract the full task block (Goal → Deliverables → SRS reference → Review checklist) — for every task in the leg.</li><li>Writes <strong><code>CURRENT_TASK.md</code></strong> in the repo root — the full spec in one file (<code>**Mode:** task</code> or <code>**Mode:** leg</code>), no further navigation needed.</li><li>Reads the relevant RFC(s) if referenced.</li><li>Prints a summary and creates the branch (<code>feat/&lt;workstream-slug&gt;-leg-&lt;n&gt;</code> for a leg).</li></ol><h3 id="during-implementation" tabindex="-1">During implementation <a class="header-anchor" href="#during-implementation" aria-label="Permalink to &quot;During implementation&quot;">​</a></h3><p>Read <code>CURRENT_TASK.md</code> for task context at any point. It contains everything: goal, deliverables, and the review checklist. No need to re-open the epic file or roadmap mid-task.</p><h3 id="completing-a-task" tabindex="-1">Completing a task <a class="header-anchor" href="#completing-a-task" aria-label="Permalink to &quot;Completing a task&quot;">​</a></h3><p>Run <code>/sv-task-complete</code>. Verification runs first, followed by any security review and required version bumps; task-document updates run only after the final root version is known:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/sv-verify          — runs all checks, returns structured pass/fail summary</span></span>
<span class="line"><span>/sv-security-check  — only if diff touches auth, middleware, API routes,</span></span>
<span class="line"><span>                      server actions, SDK/manifest, bin/, Docker, or env</span></span>
<span class="line"><span>main agent          — applies required version bumps</span></span>
<span class="line"><span>/sv-update-task-docs— records version, relocates/completes roadmap row,</span></span>
<span class="line"><span>                      updates epic heading, deletes CURRENT_TASK.md</span></span>
<span class="line"><span>main agent          — prepares PR description</span></span>
<span class="line"><span>/sv-create-pr       — creates the GitHub PR as a draft when requested</span></span></code></pre></div><p><strong><code>/sv-verify</code></strong> reads <code>CURRENT_TASK.md</code>, runs <code>format:check</code>, <code>lint</code>, <code>typecheck</code>, <code>design:tokens:check</code>, <code>docs:check-links</code>, <code>test</code>, and <code>build</code> (plus docs-parity, UI typecheck, and <code>registry:check</code> when relevant), checks the version-bearing docs agree with <code>package.json</code>, and returns a summary table — not raw output. Failures block the PR draft.</p><p><strong><code>/sv-update-task-docs</code></strong> reads <code>CURRENT_TASK.md</code> for metadata, records the final root platform version when one was bumped, moves completed rows out of Non-prioritised Tasks into the correct client phase, marks the roadmap row(s) and matching epic heading(s) ✅, updates the <code>Status:</code> line of any RFC the work advances (and its row in <code>docs/rfcs/README.md</code>), appends a workstream changelog row in leg mode, and deletes <code>CURRENT_TASK.md</code>. It does not append completion entries to <code>CLAUDE.md</code> or <code>AGENTS.md</code> — <code>ROADMAP.md</code>, the task&#39;s epic heading, and the PR body are the canonical record.</p><p><strong><code>/sv-security-check</code></strong> (conditional) reviews the diff against the security-relevant hard rules (<code>docs/architecture-rules.md</code>) — server-action authorization, <code>/api/admin</code> trust, middleware redirects/matcher/CSP, secrets, spawned processes, SDK permission checks. Violations block the PR draft.</p><p><strong><code>/sv-create-pr</code></strong> creates the GitHub pull request. Agent-created PRs are always opened as <strong>draft</strong> PRs first with <code>gh pr create --draft</code>, even when the human simply says &quot;create the PR&quot;. Mark a PR ready for review only after explicit human instruction.</p><hr><h2 id="status-tracking" tabindex="-1">Status tracking <a class="header-anchor" href="#status-tracking" aria-label="Permalink to &quot;Status tracking&quot;">​</a></h2><p>Status lives in exactly two places:</p><table tabindex="0"><thead><tr><th>Location</th><th>What it tracks</th></tr></thead><tbody><tr><td><code>ROADMAP.md</code> row Status cell</td><td>per task — the canonical record</td></tr><tr><td>Open PRs</td><td>Which tasks are currently in flight</td></tr></tbody></table><p>Status values, used identically in <code>ROADMAP.md</code> rows and epic headings:</p><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th></tr></thead><tbody><tr><td>📋</td><td>Planned — not started</td></tr><tr><td>⏳</td><td>In progress — a branch/PR is open for it</td></tr><tr><td>✅</td><td>Complete — merged to <code>main</code></td></tr><tr><td>🚧</td><td>Parked — deliberately paused; the heading names what must be re-read before resuming (e.g. 17.4, 8.20)</td></tr><tr><td>❌</td><td>Rejected — decided against, kept for the record (e.g. 2.20, 8.19, 9.13); never delete the row or heading</td></tr></tbody></table><p><strong>Epic file headings (<code>#### ✅ X.Y — …</code>) are updated when a task completes.</strong> To close a task, mark both the roadmap row and the matching <code>docs/epics/&lt;file&gt;.md</code> task heading ✅ in the same PR.</p><hr><h2 id="current-task-md-—-the-active-task-file" tabindex="-1"><code>CURRENT_TASK.md</code> — the active task file <a class="header-anchor" href="#current-task-md-—-the-active-task-file" aria-label="Permalink to &quot;\`CURRENT_TASK.md\` — the active task file&quot;">​</a></h2><p><code>CURRENT_TASK.md</code> is a transient, gitignored file written by <code>/sv-task-start</code> and deleted by <code>/sv-update-task-docs</code> (the last step <code>/sv-task-complete</code> runs). It is never committed. It has two modes: <strong>task</strong> (one epic task) and <strong>leg</strong> (one workstream leg — the leg&#39;s detail block plus every task block in it).</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># Current Task</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;">**Mode:**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> task</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;">**Epic task:**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 9.9</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;">**Roadmap version:**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 0.9.1</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;">**Branch:**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> feat/email-templates</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;">**Epic file:**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> docs/epics/design-system.md</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;">**RFCs:**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 0031</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">---</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">#### ⏳ 9.9 — Email template system + White-labeling Phase 2 …</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;">**Goal:**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> …</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;">**Deliverables:**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> …</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;">**SRS reference:**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> …</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;">**Review checklist:**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> …</span></span></code></pre></div><p>Leg mode uses <code>**Mode:** leg</code>, <code>**Workstream:**</code>, <code>**Leg:**</code>, <code>**Epic tasks:**</code>, and <code>**Epic files:**</code> instead, followed by a <code>## Leg detail</code> block and one <code>## Task &lt;id&gt;</code> block per task — the exact shape is in the <code>sv-task-start</code> skill.</p><p>Any agent or sub-agent working on the current task should read this file first. It is the single source of truth for what is being built right now.</p><p>If <code>CURRENT_TASK.md</code> does not exist, no task is in progress — run <code>/sv-task-start</code> to begin one.</p><hr><h2 id="cross-references-between-epics" tabindex="-1">Cross-references between epics <a class="header-anchor" href="#cross-references-between-epics" aria-label="Permalink to &quot;Cross-references between epics&quot;">​</a></h2><p>Some tasks belong primarily to one epic but are relevant to another (e.g. per-plugin database is in Plugins Runtime but is also a Data Sovereignty concern). The secondary epic contains a short cross-reference block instead of duplicating the full entry:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">#### ✅ 8.3 — Per-plugin database</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">&gt; Full entry: </span><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;">**[</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">3.13</span><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;">]**</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;"> in [</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">plugins-runtime.md</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">](</span><span style="--shiki-light:#22863A;--shiki-light-text-decoration:underline;--shiki-dark:#85E89D;--shiki-dark-text-decoration:underline;">plugins-runtime.md</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">) — Per-plugin database.</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">&gt; This task provisions the isolated storage layer that keeps plugin data physically separate</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">&gt; from the platform DB — a key component of data sovereignty.</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">---</span></span></code></pre></div><p>The <code>**[3.13]**</code> notation is the stable epic task ID. It survives task renames because it references the ID, not a markdown anchor.</p><hr><h2 id="version-identifiers" tabindex="-1">Version identifiers <a class="header-anchor" href="#version-identifiers" aria-label="Permalink to &quot;Version identifiers&quot;">​</a></h2><p>When a PR bumps a package version, use the release identifier as the version-bump commit subject and as the release tag:</p><table tabindex="0"><thead><tr><th>Versioned target</th><th>Commit subject / tag</th></tr></thead><tbody><tr><td>Root <code>package.json</code></td><td><code>vX.Y.Z</code></td></tr><tr><td><code>packages/ui</code></td><td><code>ui-vX.Y.Z</code></td></tr><tr><td><code>packages/sdk</code></td><td><code>sdk-vX.Y.Z</code></td></tr><tr><td>Any other package/app/plugin tag</td><td><code>&lt;slug&gt;-vX.Y.Z</code></td></tr></tbody></table><p>Use the package slug from the workspace path unless a public release workflow defines a more specific slug.</p><hr><h2 id="role-agents" tabindex="-1">Role agents <a class="header-anchor" href="#role-agents" aria-label="Permalink to &quot;Role agents&quot;">​</a></h2><p>Focused skills cover the non-implementation phases of a task. Each needs only <code>CURRENT_TASK.md</code> plus its own skill file — no full project orientation required. The skills live in <code>.agents/skills/</code> (Codex) and <code>.claude/skills/</code> (Claude Code) as byte-identical copies; <code>scripts/__tests__/agent-skills-sync.test.ts</code> fails CI if they diverge, so edit one and copy to the other.</p><table tabindex="0"><thead><tr><th>Skill</th><th>Trigger</th><th>What it does</th></tr></thead><tbody><tr><td><code>/sv-task-start</code></td><td>Session start, with a task or leg assignment</td><td>Writes CURRENT_TASK.md (task or leg mode), creates the branch</td></tr><tr><td><code>/sv-ui-design</code></td><td>Any change a user sees</td><td>DS-first rules, plain-language copy, error UX, wireframe-before-build, pre-merge checklist</td></tr><tr><td><code>/sv-task-complete</code></td><td>Implementation done</td><td>Orchestrates the four steps below in order, then drafts the PR description</td></tr><tr><td><code>/sv-verify</code></td><td>Step 1 of task-complete, or standalone</td><td>Runs all checks, returns a structured pass/fail table</td></tr><tr><td><code>/sv-security-check</code></td><td>Step 2, conditional — auth, middleware, API, server actions, SDK, bin, Docker</td><td>Reviews the diff against the security-relevant hard rules, blocks the PR on a violation</td></tr><tr><td><code>/sv-update-task-docs</code></td><td>Step 4, after the version bump</td><td>Marks roadmap row(s) and epic heading(s) ✅, syncs RFC/workstream status, deletes CURRENT_TASK.md</td></tr><tr><td><code>/sv-create-pr</code></td><td>Only when the developer asks</td><td>Opens the GitHub PR as a draft</td></tr></tbody></table><p>Each agent is briefed with <code>CURRENT_TASK.md</code> rather than the full project context. The steps run <strong>sequentially</strong>, not in parallel: verification must pass before anything else, and the docs updater needs the final root version from the bump step, so it runs last.</p><hr><h2 id="quick-reference-for-agents" tabindex="-1">Quick reference for agents <a class="header-anchor" href="#quick-reference-for-agents" aria-label="Permalink to &quot;Quick reference for agents&quot;">​</a></h2><table tabindex="0"><thead><tr><th>I need to know…</th><th>Read…</th></tr></thead><tbody><tr><td>What task is next</td><td>Ask the developer; check <code>ROADMAP.md</code> for pending tasks</td></tr><tr><td>Full spec for the current task</td><td><code>CURRENT_TASK.md</code></td></tr><tr><td>Full spec for any task by epic ID</td><td><code>docs/epics/&lt;file&gt;.md</code> — grep for <code>^#### .*&lt;id&gt;</code></td></tr><tr><td>All tasks in a domain</td><td><code>docs/epics/&lt;file&gt;.md</code></td></tr><tr><td>Roadmap version number for a task</td><td><code>ROADMAP.md</code></td></tr><tr><td>Which epic a roadmap task belongs to</td><td><code>ROADMAP.md</code> → Epic task column</td></tr><tr><td>Epic file for a given epic ID</td><td><code>docs/epics/README.md</code></td></tr><tr><td>Project conventions and hard rules</td><td><code>CLAUDE.md</code> (Claude Code) / <code>AGENTS.md</code> (Codex)</td></tr><tr><td>Full detail behind any hard rule</td><td><code>docs/architecture-rules.md</code></td></tr><tr><td>Security rules to check against</td><td><code>docs/architecture-rules.md</code> via <code>/sv-security-check</code></td></tr><tr><td>How a task or leg is run end to end</td><td><code>.agents/skills/sv-*/SKILL.md</code> (mirrored in <code>.claude/</code>)</td></tr></tbody></table>`,72)])])}const g=t(o,[["render",n]]);export{k as __pageData,g as default};
